package com.gamelab.domain;
import com.gamelab.pattern.factory.EnemyType;
import java.util.*;
/** Immutable enemy composition for a campaign wave. Spawn positions are supplied by the game layer. */
public final class WaveDefinition { private final int number; private final String stageName; private final Map<EnemyType,Integer> composition; private final boolean bossWave; public WaveDefinition(int number,String stageName,Map<EnemyType,Integer> composition,boolean bossWave){if(number<=0||stageName==null||stageName.isBlank()||composition==null||composition.isEmpty())throw new IllegalArgumentException("Invalid wave definition");Map<EnemyType,Integer> copy=new LinkedHashMap<>();composition.forEach((t,c)->{if(t==null||c==null||c<=0)throw new IllegalArgumentException("Invalid enemy count");copy.put(t,c);});this.number=number;this.stageName=stageName;this.composition=Collections.unmodifiableMap(copy);this.bossWave=bossWave;} public int getNumber(){return number;} public String getStageName(){return stageName;} public Map<EnemyType,Integer> getComposition(){return composition;} public boolean isBossWave(){return bossWave;} public int getTotalEnemies(){return composition.values().stream().mapToInt(Integer::intValue).sum();} }
